//! Evaluator access to pattern matching and IR literals.
//!
//! The implementations live in [`crate::patterns`] as free functions, so code generated by
//! `rite build` reaches the same matcher rather than carrying its own. These are the thin
//! methods the tree-walker calls.

use super::*;
use crate::value::Value;
use rite_sem::{PatternIr, ValueLiteral};

impl Evaluator<'_> {
    pub(super) fn match_pattern(
        &self,
        pat: &PatternIr,
        value: &Value,
    ) -> Result<Option<Vec<(String, Value)>>, EvalError> {
        crate::patterns::match_pattern(&self.ctx.atoms, pat, value)
    }

    pub(super) fn lit_to_value(&self, lit: &ValueLiteral) -> Value {
        crate::patterns::literal_value(lit)
    }
}
